const canadaAnswers=canadaSection();
Object.assign(frenchDictionary,canadaTranslations);
Object.assign(frenchDictionary,photoTranslations);
Object.assign(frenchDictionary,featureTranslations,commerceTranslations);
for(const a of articles){const words=[a.answer,...a.sections.flat()].join(' ').trim().split(/\s+/).length;a.read=Math.max(1,Math.ceil(words/200))+' min';}
const root=path.resolve(import.meta.dirname,'../dist');
await fs.mkdir(root,{recursive:true});
await fs.cp(path.resolve(import.meta.dirname,'assets'),path.join(root,'assets'),{recursive:true,filter:src=>!src.endsWith('.png')});
for(const file of ['styles.css','app.js','commerce.css','commerce.js','admin-data.js','admin.js']) await fs.copyFile(path.join(import.meta.dirname,file),path.join(root,'assets',file));
await fs.writeFile(path.join(root,'assets/locale.js'),(await fs.readFile(path.join(import.meta.dirname,'locale-runtime.js'),'utf8')).replace('__FRENCH_DICTIONARY__',JSON.stringify(frenchDictionary)));
const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const json=x=>JSON.stringify(x).replaceAll('<','\\u003c');
const money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:site.currency,maximumFractionDigits:2}).format(n);
const icon=(name='tv')=>`<svg viewBox="0 0 24 24" aria-hidden="true">${({tv:'<rect x="2" y="4" width="20" height="14" rx="2"/><path d="M8 22h8M12 18v4"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',laptop:'<path d="M5 17V4h14v13M2 17h20l-2 4H4z"/>',stick:'<rect x="7" y="3" width="10" height="17" rx="3"/><circle cx="12" cy="8" r="2"/><path d="M10 14h4M10 17h4"/>',box:'<rect x="3" y="4" width="18" height="16" rx="4"/><path d="M8 16h8"/>',play:'<path d="m9 5 11 7-11 7z"/>',layers:'<path d="m12 2 10 6-10 6L2 8zM2 12l10 6 10-6M2 16l10 6 10-6"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',menu:'<path d="M5 8h14M5 16h14"/>',pause:'<path d="M8 5v14M16 5v14"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z"/><path d="m8 11 3 3 5-6"/>'})[name]||''}</svg>`;
const btn=(href,label,style='primary')=>`<a class="btn ${style}" href="${href}">${label}</a>`;
const link=(href,label)=>`<a class="text-link" href="${href}">${label}</a>`;
const mark=()=>`<span class="brand-mark lumina-mark" aria-hidden="true"><svg viewBox="0 0 32 32"><rect x="3" y="5" width="26" height="19" rx="5"/><path class="logo-play" d="m13 10 8 4.5-8 4.5z"/><path d="M11 28h10"/></svg></span><span class="brand-name">Lumina <span>Stream</span></span>`;
const catalog = {plans,trial,currency:site.currency,preview:site.preview,paymentLinks:{}};
const pages=[];
function header(route){const nav=[['/subscription/','Plans'],['/channels/','Channels'],['/devices/','Devices'],['/guide/','Setup'],['/faq/','FAQ'],['/blog/','Journal']];return `<a class="skip" href="#main">Skip to content</a><div class="scroll-progress" aria-hidden="true"></div>${site.preview?'<div class="preview-bar">Website preview · Example plans · No live payments <a href="/about/#preview">About this preview</a></div>':''}<header class="site-header"><a class="brand" href="/" aria-label="Relay TV home">${mark()}</a><nav class="nav" id="main-nav" aria-label="Main navigation">${nav.map(([u,t])=>`<a href="${u}"${route.startsWith(u)?' aria-current="page"':''}>${t}</a>`).join('')}<a class="mobile-contact" href="/contact/">Contact</a></nav><div class="header-actions"><div class="site-preferences"><a class="language-toggle" href="/fr/" data-language-toggle lang="fr" aria-label="Afficher le site en français">FR</a><button class="theme-toggle" type="button" aria-label="Switch to light mode" aria-pressed="false"><span class="theme-sun" aria-hidden="true">☀</span><span class="theme-moon" aria-hidden="true">☾</span></button></div>${btn('/free-trial/','Try it first','primary small')}<button class="menu-toggle" aria-label="Open navigation" aria-controls="main-nav" aria-expanded="false">${icon('menu')}</button></div></header>`}
function footer(){return `<section class="closing"><div class="wrap reveal"><span class="eyebrow" style="justify-content:center">Make yourself comfortable</span><h2>Good evenings<br><span class="chrome">start here.</span></h2><p>Find your screen. Pick your plan. Make a little more room for the things you love watching.</p><div class="actions">${btn('/subscription/','Explore the plans')}${btn('/contact/','Ask a question','')}</div></div></section><footer class="footer"><div class="wrap"><div class="footer-top"><div class="footer-brand"><a class="brand" href="/" aria-label="Relay TV home">${mark()}</a><p>TV time, thoughtfully connected.<br>A clearer way to choose, set up and settle in.</p><small>Canada-focused website preview.<br>Service availability to be confirmed.</small></div><div><h4>Find your evening</h4><div class="footer-links"><a href="/subscription/">Subscription plans</a><a href="/free-trial/">24-hour trial</a><a href="/channels/">Viewing categories</a><a href="/devices/">Supported devices</a></div></div><div><h4>A little help</h4><div class="footer-links"><a href="/guide/">Setup guides</a><a href="/faq/">Questions & answers</a><a href="/contact/">Contact</a><a href="/blog/">The Relay journal</a></div></div><div><h4>Closer to home</h4><div class="footer-links"><a href="/iptv-canada/">Canada checklist</a><a href="/guide/">Setup guides</a><a href="/faq/">Subscription FAQ</a><a href="/about/">About Relay TV</a></div></div></div><div class="footer-bottom"><span>© 2026 ${site.name}. ${site.preview?'Design & service preview.':''}</span><div class="actions"><a href="/privacy/">Privacy</a><a href="/terms/">Service terms</a><a href="/refund-policy/">Refund information</a></div><span>Made for your downtime.</span></div><div class="footer-large" aria-hidden="true">Lumina Stream</div></div></footer><button class="motion-toggle" aria-label="Pause decorative animations" aria-pressed="false" title="Pause decorative animations">${icon('pause')}</button>`}
function breadcrumb(label,parent){return `<nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span>${parent?`<a href="${parent[0]}">${parent[1]}</a><span aria-hidden="true">/</span>`:''}<span aria-current="page">${escape(label)}</span></nav>`}
function hero({eyebrow,title,intro,label,parent,actions=''}){return `<section class="page-hero"><div class="wrap">${breadcrumb(label||eyebrow,parent)}<div class="reveal"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${intro?`<p>${intro}</p>`:''}${actions?`<div class="actions">${actions}</div>`:''}</div></div></section>`}
const answer=(text,title='The short answer')=>`<div class="answer-box"><span class="eyebrow">${title}</span><p>${text}</p></div>`;
function faqList(items){return `<div class="faq-list">${items.map(f=>`<details class="faq-item" data-question="${escape(f.q+' '+f.a)}"><summary>${f.q}</summary><p>${f.a}</p></details>`).join('')}</div>`}
const articleCard=a=>`<article class="article-card reveal" data-category="${a.category}" data-search="${escape(a.title+' '+a.description+' '+a.category)}"><a class="article-img" href="/blog/${a.slug}/"><img src="/assets/${a.image}" alt="${escape(a.imageAlt)}" width="800" height="500" loading="lazy"></a><div class="article-meta"><span class="tag">${a.category}</span><span>${a.read} read</span></div><h3><a href="/blog/${a.slug}/">${a.title}</a></h3><p>${a.description}</p>${link('/blog/'+a.slug+'/','Read the guide')}</article>`;
function deviceCard(d){return `<article class="card device-card reveal" data-category="${d.category}"><div class="icon">${icon(d.icon)}</div><h3>${d.name}</h3><p>${d.text}</p>${link('/guide/'+d.id+'/','View setup checklist')}</article>`}
function trialBanner(){return `<div class="trial-banner"><div><h3>A little trial. A much easier decision.</h3><p>24 hours · 1 stream · CAD ${trial.price.toFixed(2)} example price</p></div>${btn('/free-trial/','Explore the trial','')}</div>`}
async function page(route,title,description,body,options={}){
 const brandText=s=>s.replaceAll('Relay TV','Lumina Stream').replaceAll('The Relay','The Lumina').replaceAll('the Relay','the Lumina').replaceAll('relay television','lumina stream').replaceAll('relay TV','lumina stream').replaceAll('RELAY','LUMINA');
 title=storefrontCopy(brandText(title));description=storefrontCopy(brandText(description));body=canadaCopy(storefrontCopy(brandText(businessPage(route)||body)));
 if(canadaMetadata[route])[title,description]=canadaMetadata[route];
 if(['/','/subscription/','/iptv-canada/'].includes(route))body+=canadaAnswers;
 if(route==='/checkout/')body=body.replace(/<div data-checkout-step="2" hidden>[\s\S]*?<\/form>/,'</form>'+paymentPanel()+'<p class="status" data-commerce-status role="status"></p>');
 if(route==='/'){const section=body.match(/<section class="section band" id="plans">[\s\S]*?<\/section>/)?.[0];if(section){body=body.replace(section,'');const end=body.indexOf('</section>',body.indexOf('<section class="device-rail"'))+10;body=body.slice(0,end)+section+body.slice(end);}}
 const canonical=site.origin+route;
 const noindex=!site.indexing||options.noindex;
 const schema=[{'@type':'Organization','@id':site.origin+'/#organization',name:site.name,url:site.origin+'/',logo:site.origin+'/assets/logo.svg'}, {'@type':'WebSite','@id':site.origin+'/#website',name:site.name,url:site.origin+'/',inLanguage:'en-CA'}, {'@type':'WebPage','@id':canonical+'#page',url:canonical,name:title,description,inLanguage:'en-CA',isPartOf:{'@id':site.origin+'/#website'},dateModified:site.updated}];
 if(route!=='/')schema.push({'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:site.origin+'/'},{'@type':'ListItem',position:2,name:options.label||title.split('|')[0].trim(),item:canonical}]});
 if(options.schema)schema.push(...options.schema);
 schema[0].areaServed={'@type':'Country',name:'Canada',identifier:'CA'};
 schema[2].spatialCoverage={'@type':'Country',name:'Canada',identifier:'CA'};
 if(['/','/subscription/','/iptv-canada/'].includes(route)){
  schema.push({'@type':'FAQPage',mainEntity:canadaFaqs.map(f=>({'@type':'Question',name:f.q,acceptedAnswer:{'@type':'Answer',text:f.a}}))});
  schema.push({'@type':'Service','@id':canonical+'#service',name:site.name,serviceType:'IPTV',provider:{'@id':site.origin+'/#organization'},areaServed:{'@type':'Country',name:'Canada',identifier:'CA'},url:canonical});
 }
 const html=`<!doctype html><html lang="en-CA"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="theme-color" content="#080b0a"><title>${escape(title)}</title><meta name="description" content="${escape(description)}"><meta name="robots" content="${noindex?'noindex, follow':'index, follow, max-image-preview:large'}"><link rel="canonical" href="${canonical}"><meta property="og:type" content="${options.article?'article':'website'}"><meta property="og:site_name" content="${site.name}"><meta property="og:title" content="${escape(title)}"><meta property="og:description" content="${escape(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${site.origin}/assets/hero-real.jpg"><meta property="og:image:alt" content="Lumina Stream television and movie night at home"><meta property="og:locale" content="en_CA"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${escape(title)}"><meta name="twitter:description" content="${escape(description)}"><meta name="twitter:image" content="${site.origin}/assets/hero-real.jpg"><link rel="icon" href="/assets/logo.svg" type="image/svg+xml"><link rel="preload" href="/assets/rethink-sans.woff2" as="font" type="font/woff2" crossorigin>${route==='/'?'<link rel="preload" href="/assets/hero-real.jpg" as="image" fetchpriority="high">':''}<script>{let t="system";try{t=localStorage.getItem("lumina:theme")||"system";}catch{}document.documentElement.dataset.themePreference=t;document.documentElement.dataset.theme=t==="light"||t!=="dark"&&matchMedia("(prefers-color-scheme: light)").matches?"light":"dark";}</script><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">${json({'@context':'https://schema.org','@graph':schema})}</script><script id="site-catalog" type="application/json">${json(catalog)}</script><script defer src="/assets/locale.js"></script><script defer src="/assets/app.js"></script></head><body data-page="${route}">${header(route)}<main id="main">${body}</main>${options.checkout?'':footer()}</body></html>`;
 const enhanced=html.replace('</head>','<link rel="stylesheet" href="/assets/commerce.css"><meta name="referrer" content="no-referrer"><script defer src="/assets/commerce.js"></script><script defer src="/assets/admin-data.js"></script><script defer src="/assets/admin.js"></script></head>'); const en=refreshPhotography(commerceCopy(storefrontCopy(brandText(enhanced))),route).replaceAll('—',', ').replaceAll('&#8212;',', ').replaceAll('&mdash;',', ').replace('</head>',alternateLinks(route,site.origin)+'</head>').replace(/(<a class="language-toggle"[^>]*href=")[^"]+/,`$1/fr${route}`); const fr=translatePage(en,route,site.origin); for(const [url,content,lang] of [[route,en,'en-CA'],['/fr'+route,fr,'fr-CA']]){const dest=path.join(root,url.slice(1),'index.html');await fs.mkdir(path.dirname(dest),{recursive:true});await fs.writeFile(dest,content);pages.push({route:url,title:lang==='fr-CA'?translate(title):title,description:lang==='fr-CA'?translate(description):description,noindex,lang,kind:options.article?'article':'page'});}
}
await fs.writeFile(path.join(root,'assets/logo.svg'),`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="17" fill="#c4f277"/><g stroke="#11190e" stroke-width="3.5" fill="none" stroke-linecap="round"><rect x="10" y="13" width="44" height="32" rx="8"/><path d="M24 53h16"/></g><path d="m27 21 14 8-14 8z" fill="#11190e"/></svg>`);
