await page('/free-trial/','24-Hour IPTV Trial Preview | Relay TV','Explore the proposed 24-hour IPTV trial: CAD 2.99, one stream and a practical checklist for testing your device and viewing list.',hero({eyebrow:'Try your own kind of evening',title:'A little trial.<br><span class="chrome">A clearer choice.</span>',intro:'Check your screen, your connection and your favourites before a longer commitment.',label:'24-hour trial'})+`<section class="section small"><div class="wrap split"><div class="trial-visual"><img src="/assets/cinema-real.jpg" alt="Real cinema seating before a movie" width="1200" height="800"><div><span class="pill accent">PROPOSED TRIAL</span><h2 style="margin-top:20px">24 hours.<br>Your own screen.</h2></div></div><div>${answer('The example trial is CAD 2.99 for 24 hours on one simultaneous stream. This preview cannot take a payment or activate access.','Trial at a glance')}<h3>Make your trial count.</h3><ul><li>Use the television or device you plan to watch on.</li><li>Check the specific channels and languages you need.</li><li>Try it during your usual viewing hours.</li><li>Explore the player and programme guide, if included.</li><li>Confirm the final trial and renewal terms first.</li></ul>${btn('/checkout/?plan=trial&screens=1','Preview the trial checkout')}<p class="privacy-line">No payment taken. No access issued.</p></div></div></section>`);
