await page('/channels/','IPTV Channel & Viewing Availability Checklist | Relay TV','Explore viewing categories and create a channel availability request. Confirm your exact channels, languages and region before choosing an IPTV plan.',hero({eyebrow:'Find what matters to you',title:'Your world.<br><span class="chrome">Your kind of watching.</span>',intro:'A great lineup starts with your favourites. Explore the categories below and build a list to check before you choose a plan.',label:'Viewing categories'})+`<section class="section small"><div class="wrap" data-channel-browser>${answer('These are viewing interests, not a confirmed channel catalogue. Specific channels, programmes, resolution and regional availability must be checked before purchase.','A clearer channel list')}<div class="search-field">${icon('search')}<label class="sr-only" for="channel-search">Search viewing categories</label><input id="channel-search" type="search" placeholder="Search a language, interest or category…" data-channel-search></div><p class="result-count" aria-live="polite" data-channel-count>8 viewing categories</p><div class="grid-3" data-channel-grid>${channelCategories.map(([id,name,text])=>`<article class="card channel-card reveal" data-channel-card data-category="${id}" data-search="${escape(id+' '+name+' '+text)}"><span class="count">Viewing interest</span><h3>${name}</h3><p>${text}</p><label class="check-label"><input type="checkbox" name="interest" value="${id}">Add to my request</label></article>`).join('')}</div><p class="no-results" data-channel-empty hidden>No matching category. You can ask support about any specific channel.</p><div class="channel-request"><div><strong><span data-selected-count>0</span> interests selected</strong><p>We’ll add them to your availability enquiry.</p></div><a class="btn primary" href="/contact/?topic=Channel%20availability" data-channel-request>Ask about availability</a></div></div></section>`);
await page('/devices/','IPTV Device Compatibility Checklist | Relay TV','Check IPTV setup requirements for Fire TV, Android TV, Apple TV, Samsung and LG TVs, phones, Windows and Mac. Confirm your exact model before ordering.',hero({eyebrow:'Keep the screen you love',title:'Your sofa.<br>Your screen.<br><span class="chrome">Your kind of simple.</span>',intro:'Start with what you already own. Then check the model, player and connection that bring it all together.',label:'Devices'})+`<section class="section small"><div class="wrap" data-filter-grid>${answer('Compatibility depends on the exact device model, operating system, regional app store and the player supported by the final service. These checklists help you confirm those details.')}<div class="filters" aria-label="Filter devices">${['All','TV devices','Smart TVs','Mobile','Computers'].map((x,i)=>`<button class="filter" data-grid-filter="${x}" aria-pressed="${!i}">${x}</button>`).join('')}</div><div class="grid-3" data-grid>${devices.map(deviceCard).join('')}</div><p class="caption">Brand names identify device families. They do not imply a partnership or endorsement.</p></div></section>`);
await page('/guide/','IPTV Setup Guides by Device | Relay TV','Get a clear IPTV setup checklist for your television, streaming device, phone or computer. Learn what to check before installing a player or adding an account.',hero({eyebrow:'A good start makes all the difference',title:'Less figuring out.<br><span class="chrome">More settling in.</span>',intro:'Choose your device for a focused setup checklist. No mysterious downloads. No guessing which details you need.',label:'Setup guides'})+`<section class="section small"><div class="wrap"><div class="grid-3">${devices.map(deviceCard).join('')}</div></div></section><section class="section band"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Before the first watch</span><h2>Three things<br><span class="chrome">to have ready.</span></h2></div></div><div class="grid-3"><div class="card"><div class="icon">${icon('tv')}</div><h3>Your exact device.</h3><p>Find the model and operating system. Check the supported player in its official app store.</p></div><div class="card"><div class="icon">${icon('layers')}</div><h3>Your connection.</h3><p>Use the network you plan to watch on. Compare Ethernet where your hardware supports it.</p></div><div class="card"><div class="icon">${icon('shield')}</div><h3>Your account details.</h3><p>Use only credentials issued by your authorised provider. Keep passwords and playlist URLs private.</p></div></div></div></section>`);
